    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
        AgeBand band = AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate());
        return (band == null) ? null : OwnerDto.AgeBandEnum.valueOf(band.name());
    }

